export function counterfactualAnalysis(inputData, testCases) {
  const counterfactuals = [];

  testCases.forEach(testCase => {
    const modifiedData = generateCounterfactual(inputData, testCase);
    const result = evaluate(modifiedData);
    counterfactuals.push({ testCase, result });
  });

  return counterfactuals;
}

function generateCounterfactual(data, testCase) {
  return { ...data, ...testCase };
}

function evaluate(data) {
  return `Evaluation result for ${JSON.stringify(data)}`;
}